local switchMorphologyCoolDown = 1.5  -- 切换形态的冷却时间
local standUpTime = 0.4 -- 人猫切换时镜头参数变化的时间点
local sitDownTime = 0.68 -- 

--local _veryFar = Vector3(99999, -99999, 99999)
local _veryFar = Vector3(0, -9999, 0) -- 设置在脚下无穷远, 是为了隐藏切换后脚步特效的异常 (一个临时的方案)




-- ========================================================


function SwitchablePlayerController:__init()
    self.controller = nil

    self._switchMorphologyTimer = 0.0
    self._switching = false

    -- 当进入某些 volume 时, 此值会被设为 false, 此时 人/猫状态将由 volume 管理, 无法被玩家手动修改
    self.isSwitchabledByPlayer = true

    self.morphologyType = RoleMorphologyType.None

    self._humanCharacter = nil   -- Character
    self._catCharacter = nil     -- Character
    self._humanController = nil  -- PlayerController
    self._catController = nil    -- PlayerControllerQuadruped

    self.lastRoleMoveState = RoleMoveState.MoveEnd --  最后一次更新的 move 状态, 以便新 switch in 的 human/cat 可以知道自己的动画/运动状态

end





function SwitchablePlayerController:__delete()
    self.co_1 = nil
    self.co_human = nil
    self.co_cat = nil
end



function SwitchablePlayerController:Awake()
    KTool.SetActive(self.controller.gameObject, true)
    self.transform = self.controller.gameObject.transform
end



function SwitchablePlayerController:Init( humanCharacter,humanController, catCharacter, catController, initMorphologyType, initDir_)
    KTool.SetActive(self.controller.gameObject, true)

    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:
    assert(GlobalsInDreamSpace.GetStringState("MorphologyType") == "") -- 为空

    assert( initMorphologyType==RoleMorphologyType.Cat or initMorphologyType==RoleMorphologyType.Human )
    
    if initMorphologyType==RoleMorphologyType.Cat then 
        assert( isNotNull(catCharacter) and isNotNull(catController) )
    else 
        assert( isNotNull(humanCharacter) and isNotNull(humanController) )
    end 

    -- 是否支持人猫切换:
    self.isSupportHuman = isNotNull(humanCharacter) and isNotNull(humanController)
    self.isSupportCat   = isNotNull(catCharacter) and isNotNull(catController)
    

    self._humanCharacter = humanCharacter
    self._humanController = humanController
    self._catCharacter = catCharacter
    self._catController = catController

    self:SetMorphologyType( initMorphologyType )

    assert( self.fx_toHuman and self.fx_toCat )
    self.fx_toHuman.position = _veryFar
    self.fx_toCat.position = _veryFar
    KTool.SetActive( self.fx_toHuman.gameObject, false )
    KTool.SetActive( self.fx_toCat.gameObject, false )

    ---
    self.lastRoleMoveState = RoleMoveState.MoveEnd

    local initRotation = Quaternion.LookRotation( Vector3.ProjectOnPlane( initDir_, Vector3.up ), Vector3.up )

    if self.morphologyType == RoleMorphologyType.Human then
        self:InitWithHuman(initRotation)
    elseif self.morphologyType == RoleMorphologyType.Cat then
        self:InitWithCat(initRotation)
    end
end



function SwitchablePlayerController:SetVTargetFollow( vTargetFollow )
    self.role = vTargetFollow
end


function SwitchablePlayerController:OnDestroy()

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    DreamSpaceLuaUtils.StopCoroutine( self.co_human )
    DreamSpaceLuaUtils.StopCoroutine( self.co_cat )
    self.co_1 = nil
    self.co_human = nil
    self.co_cat = nil

    local mTypeStr = GlobalsInDreamSpace.GetStringState("MorphologyType")
    assert(mTypeStr == "Cat" or mTypeStr == "Human") -- 不为空
    GlobalsInDreamSpace.SetStringState("MorphologyType", "")
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


function SwitchablePlayerController:Update()
    if self._switching then
        self._switchMorphologyTimer = self._switchMorphologyTimer + Time.deltaTime
        if self._switchMorphologyTimer > switchMorphologyCoolDown then
            self._switchMorphologyTimer = 0
            self._switching = false
        end
    end
end




-- =========================================== Self ================================================ --



function SwitchablePlayerController:SetMorphologyType(t_)
    self.morphologyType = t_

    local val = (t_ == RoleMorphologyType.Cat) and "Cat" or 
                ( (t_ == RoleMorphologyType.Human) and "Human" or "None" )

    GlobalsInDreamSpace.SetStringState( "MorphologyType", val );
end


function SwitchablePlayerController:IntoCatVolume()
    -- 进入猫区:
    self.isSwitchabledByPlayer = false
    if self.morphologyType ~= RoleMorphologyType.Cat then
        self:Switch(false)
    end
end


function SwitchablePlayerController:IntoHumanVolume()
    -- 进入人区:
    self.isSwitchabledByPlayer = false
    if self.morphologyType ~= RoleMorphologyType.Human then
        self:Switch(false)
    end
end

function SwitchablePlayerController:LeaveAnyVolume()
    -- 从 猫区/人区离开:
    self.isSwitchabledByPlayer = true
end


-- =========================================== Input ================================================ --

function SwitchablePlayerController:MoveStart()
    self.lastRoleMoveState = RoleMoveState.MoveStart
    if self.morphologyType == RoleMorphologyType.Human then
        self._humanController:MoveStart()
    elseif self.morphologyType == RoleMorphologyType.Cat then
        self._catController:MoveStart()
    end
end


function SwitchablePlayerController:Move(moveInput)
    self.lastRoleMoveState = RoleMoveState.Moving
    if self.morphologyType == RoleMorphologyType.Human then
        self._humanController:Move(moveInput)
    elseif self.morphologyType == RoleMorphologyType.Cat then
        self._catController:Move(moveInput)
    end
end


function SwitchablePlayerController:MoveEnd()
    self.lastRoleMoveState = RoleMoveState.MoveEnd
    if self.morphologyType == RoleMorphologyType.Human then
        self._humanController:MoveEnd()
    elseif self.morphologyType == RoleMorphologyType.Cat then
        self._catController:MoveEnd()
    end
end


function SwitchablePlayerController:JumpUp()
    if self.morphologyType == RoleMorphologyType.Cat then
        self._catController:JumpUp()
    end
end


function SwitchablePlayerController:JumpDown()
    if self.morphologyType == RoleMorphologyType.Cat then
        self._catController:JumpDown()
    end
end


function SwitchablePlayerController:JumpForward()
    if self.morphologyType == RoleMorphologyType.Cat then
        self._catController:JumpForward()
    end
end


function SwitchablePlayerController:Switch(isByPlayer_)
    if self.isSupportHuman ~= true or self.isSupportCat ~= true then 
        printError("不支持 人猫切换, 请检测代码或配置; isSupportHuman = " .. tostring(self.isSupportHuman) .. ", isSupportCat = " .. tostring(self.isSupportCat) )
        return
    end

    if isByPlayer_ and not self.isSwitchabledByPlayer then
        return
    end
    -- 若 isByPlayer_ == false, 意味着是 volume 系统在强制切换角色, 此时应该无视冷却时间
    if isByPlayer_ and self._switching then
        return
    end

    self._switching = true
    self._switchMorphologyTimer = 0

    if self.morphologyType == RoleMorphologyType.Human then

        DreamSpaceLuaUtils.StopCoroutine( self.co_human )
        self.co_human = cs_coroutine.start(function()
            self:_SwitchToCat()
        end) 

    elseif self.morphologyType == RoleMorphologyType.Cat then

        DreamSpaceLuaUtils.StopCoroutine( self.co_cat )
        self.co_cat = cs_coroutine.start(function()
            self:_SwitchToHuman()
        end) 


    end
end


function SwitchablePlayerController:Attack()
    if self.morphologyType == RoleMorphologyType.Human then
        self._humanController:Attack()
    end
end

function SwitchablePlayerController:Meow()
    if self.morphologyType == RoleMorphologyType.Cat then
        self._catController:Meow()
    end
end

-- =========================================================================================== --


function SwitchablePlayerController:InitWithHuman(initRotation_)
    EventsModule.Broadcast(GameContants.MorphologyToHuman)
    if self.isSupportCat == true then 
        -- 移走当前character
        self._catCharacter.transform.position = _veryFar
        self._catCharacter.useGravity = false
        -- 这时候不要播小动作，不然切换的时候会一上来就躺着
        self._catController.playIdleMotion = false
    end
    ---
    self._humanCharacter:SetRotation(initRotation_)
end


function SwitchablePlayerController:InitWithCat(initRotation_)
    EventsModule.Broadcast(GameContants.MorphologyToCat)
    if self.isSupportHuman == true then 
        -- 移走当前character
        self._humanCharacter.transform.position = _veryFar
        self._humanCharacter.useGravity = false
    end
    ---
    self._catCharacter:SetRotation(initRotation_)
end


function SwitchablePlayerController:_SwitchToHuman()

    print( "to human -- start" )
    DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Lock ) -- 希望禁止玩家输入
    DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Lock ) -- PC 版 禁止打开 ui 子界面 

    EventsModule.Broadcast(GameContants.MorphologyToHuman)
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( standUpTime ))

    -- 当前character播动画
    self._catController:SwitchOut()

    -- 播放 猫变人 特效粒子:
    self.fx_toHuman.position = self.role.position
    self.fx_toCat.position = _veryFar
    KTool.SetActive( self.fx_toHuman.gameObject, true )
    KTool.SetActive( self.fx_toCat.gameObject, false )

    -- 播放 猫变人 声音:
    DreamSpaceSounds.Play( DreamSpaceSounds.sfx.catIntoHuman )

    -- 播特效
    coroutine.yield(Yielders.EndOfFrame)

    -- 移回切换character
    self._humanCharacter:SetRotation(self._catCharacter.transform.rotation)
    self._humanCharacter.transform.position = self._catCharacter.transform.position

    -- 切换相机
    EventsModule.Broadcast( GameContants.SwitchVirtualTargetToHuman );


    -- 移走当前character
    self._catCharacter.transform.position = _veryFar

    -- 重置 新character 的状态
    -- 切换character播动画
    self._humanController:SwitchIn(self.lastRoleMoveState, self._catCharacter.transform.rotation)
    self:SetMorphologyType( RoleMorphologyType.Human )

    print( "to human -- end" )
    DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- 解除禁止:玩家输入
    DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- PC 版 允许打开 ui 子界面 
end


function SwitchablePlayerController:_SwitchToCat()

    print( "to cat -- start" )
    DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Lock ) -- 希望禁止玩家输入
    DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Lock ) -- PC 版 禁止打开 ui 子界面 

    -- 准备切换相机参数
    if self.co_1 ~= nil then
        cs_coroutine.stop(self.co_1)
    end
    self.co_1 = cs_coroutine.start(function()
        self:_SwitchVCamParam(sitDownTime, RoleMorphologyType.Cat)
    end) 

    -- 播放 人变猫 声音:
    DreamSpaceSounds.Play( DreamSpaceSounds.sfx.humanIntoCat )

    -- 当前character播动画
    local time = self._humanController:SwitchOut()
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( time ))

    -- 播放 人变猫 特效粒子:
    self.fx_toHuman.position = _veryFar
    self.fx_toCat.position = self.role.position
    KTool.SetActive( self.fx_toHuman.gameObject, false )
    KTool.SetActive( self.fx_toCat.gameObject, true )


    -- 播特效
    coroutine.yield(Yielders.EndOfFrame)

    -- 移回切换character
    self._catCharacter:SetRotation(self._humanCharacter.transform.rotation)
    self._catCharacter.transform.position = self._humanCharacter.transform.position

    -- 切换相机
    EventsModule.Broadcast( GameContants.SwitchVirtualTargetToCat );

    -- 移走当前character
    self._humanCharacter.transform.position = _veryFar

    -- 重置 新character 的状态
    -- 切换character播动画
    self._catController:SwitchIn(self.lastRoleMoveState, self._humanCharacter.transform.rotation)
    self:SetMorphologyType( RoleMorphologyType.Cat )

    print( "to cat -- end" )
    DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- 解除禁止:玩家输入
    DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- PC 版 允许打开 ui 子界面 
end


function SwitchablePlayerController:_SwitchVCamParam(time, type)
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( time ))

    if type == RoleMorphologyType.Cat then
        EventsModule.Broadcast(GameContants.MorphologyToCat)
    elseif type == RoleMorphologyType.Human then
        EventsModule.Broadcast(GameContants.MorphologyToHuman)
    else
        assert(false, "参数 type 异常")
    end
end









return SwitchablePlayerController